<header class="page-hero compact"><div class="container"><span class="section-kicker">Admin</span><h1><?= e(t('admin.comments')) ?></h1><?php require BASE_PATH . '/views/admin/_menu.php'; ?></div></header>
<section class="section admin-section"><div class="container">
    <nav class="tabs"><a class="<?= $status === 'pending' ? 'active' : '' ?>" href="/admin/comments?status=pending">Pending</a><a class="<?= $status === 'approved' ? 'active' : '' ?>" href="/admin/comments?status=approved">Approved</a><a class="<?= $status === 'rejected' ? 'active' : '' ?>" href="/admin/comments?status=rejected">Rejected</a></nav>
    <div class="moderation-list"><?php foreach ($comments as $comment): ?><article class="admin-panel"><header><div><strong><?= e($comment['author_name']) ?></strong><span><?= str_repeat('★', (int) $comment['rating']) ?></span></div><a href="/teacher/<?= rawurlencode($comment['slug']) ?>" target="_blank"><?= e(localized($comment, 'name')) ?> ↗</a></header><p><?= nl2br(e($comment['body'])) ?></p><footer><time><?= e($comment['updated_at']) ?></time><div><?php if ($status !== 'approved'): ?><form action="/admin/comments/<?= (int) $comment['id'] ?>" method="post"><?= csrf_field() ?><input type="hidden" name="status" value="approved"><button class="button button-primary" type="submit">Approve</button></form><?php endif; ?><?php if ($status !== 'rejected'): ?><form action="/admin/comments/<?= (int) $comment['id'] ?>" method="post"><?= csrf_field() ?><input type="hidden" name="status" value="rejected"><button class="button button-danger" type="submit">Reject</button></form><?php endif; ?></div></footer></article><?php endforeach; ?><?php if (!$comments): ?><div class="empty-state">No comments in this state.</div><?php endif; ?></div>
</div></section>

